import React from "react";
import { Link } from "react-router-dom";
import heroImage from "../images/hero.jpg";

// ✅ Import REAL ProductCard
import ProductCard from "../components/ProductCard";

// 🔥 Images
import img1 from "../assets/1.jpeg";
import img2 from "../assets/2.jpeg";
import img3 from "../assets/3.jpeg";

const Home = () => {
  // ✅ Featured Products (same structure as products.js)
  const featuredProducts = [
    {
      id: 1,
      name: "Pink Baby Set",
      price: 999,
      image: img1,
      category: "Suit",
      age: "0-6 months",
    },
    {
      id: 2,
      name: "Blue Baby Set",
      price: 999,
      image: img2,
      category: "Suit",
      age: "0-6 months",
    },
    {
      id: 3,
      name: "Yellow Baby Set",
      price: 999,
      image: img3,
      category: "Suit",
      age: "0-6 months",
    },
  ];

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #fff1f8, #e6faff, #fff9e6)",
        padding: "60px 20px",
      }}
    >
      {/* HERO */}
      <div
        style={{
          maxWidth: "1000px",
          margin: "auto",
          padding: "160px 40px",
          borderRadius: "40px",
          textAlign: "center",
          backgroundImage: `url(${heroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        <h1 style={{ fontSize: "50px", color: "#d63384" }}>
          Nanhe Farishte <br /> Kiran Knits
        </h1>

        <p style={{ fontSize: "20px" }}>
          Har bunai mein maa ka pyaar 💖
        </p>

        <Link to="/products">
          <button
            style={{
              padding: "15px 40px",
              borderRadius: "30px",
              background: "#ff4f87",
              color: "#fff",
              border: "none",
              cursor: "pointer",
            }}
          >
            Shop Now
          </button>
        </Link>
      </div>

      {/* CATEGORY */}
     
<div
  style={{
    maxWidth: "1200px",
    margin: "120px auto 0", // 🔥 TOP SPACE BADHA DIYA
    textAlign: "center",
  }}
>
  <h2
    style={{
      fontSize: "38px",
      marginBottom: "50px",
      color: "#444",
      fontWeight: "700",
    }}
  >
    Our Categories
  </h2>

  <div
    style={{
      display: "flex",
      justifyContent: "center",
      gap: "40px",
      flexWrap: "wrap",
    }}
  >
    {[
      { name: "Sweater", emoji: "🧥" },
      { name: "Socks", emoji: "🧦" },
      { name: "Cap", emoji: "🧢" },
    ].map((cat) => (
      <Link
        key={cat.name}
        to={`/products?category=${cat.name}`}
        style={{ textDecoration: "none" }}
      >
        <div
          style={{
            background: "linear-gradient(135deg, #fff, #fff)",
            padding: "40px 60px", // 🔥 BIG BUTTON
            borderRadius: "30px",
            fontSize: "26px", // 🔥 BIG TEXT
            fontWeight: "700",
            color: "#333",
            boxShadow: "0 15px 35px rgba(0,0,0,0.1)",
            transition: "0.3s",
            cursor: "pointer",
            minWidth: "220px", // 🔥 SAME SIZE BUTTON
          }}
          onMouseOver={(e) => {
            e.currentTarget.style.transform = "translateY(-10px) scale(1.05)";
            e.currentTarget.style.background =
              "linear-gradient(135deg, #ffe0f0, #e0f7ff)";
          }}
          onMouseOut={(e) => {
            e.currentTarget.style.transform = "translateY(0) scale(1)";
            e.currentTarget.style.background = "#fff";
          }}
        >
          <div
            style={{
              fontSize: "45px",
              marginBottom: "12px",
            }}
          >
            {cat.emoji}
          </div>

          {cat.name}
        </div>
      </Link>
    ))}
  </div>
</div>

      {/* ✅ FEATURED PRODUCTS */}
      <div style={{ maxWidth: "1100px", margin: "80px auto" }}>
        <h2 style={{ textAlign: "center", marginBottom: "40px" }}>
          Featured Products
        </h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)",
            gap: "30px",
          }}
        >
          {featuredProducts.map((product) => (
            <ProductCard key={product.id} product={product} />
          ))}
        </div>
      </div>
    </div>
  );
};

export default Home;
